import "./style.css";
import dummyData from "../../store/photos";

const Main = () => {
  return (
    <main>
      <main>
        <section>
          <h1>Photo Gallery</h1>
          {dummyData.map(photo =>(
            <div key={photo.id} className="photo-card">
              <img src={photo.url} alt={photo.title} />
              <h3>{photo.title}</h3>
            </div>
          ))}
        </section>
      </main>
    </main>
  );
};

export default Main;
